int main() {
    int n;
    cin >> n;

    int arr[200];
    for (int i = 0; i < n; i++) {
        cin >> arr[i];
    }

    int sum = 0;
    for (int i = 0; i < n; i++) {
        if (arr[i] > 0) {
            sum += arr[i];
        }
    }

    int min_idx = 0, max_idx = 0;
    for (int i = 1; i < n; i++) {
        if (arr[i] < arr[min_idx]) {
            min_idx = i;
        }
        if (arr[i] > arr[max_idx]) {
            max_idx = i;
        }
    }

    int left = min(min_idx, max_idx);
    int right = max(min_idx, max_idx);

    int product = 1;
    for (int i = left + 1; i < right; i++) {
        product *= arr[i];
    }

    cout << sum << " " << product << endl;

    return 0;
}

