def main():
    with open('input.txt', 'r') as f:
        n = int(f.readline().strip())

    # dp[i][j] - количество лесенок из i кубиков, где нижний слой содержит j кубиков
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    # Базовый случай: одна лесенка из одного кубика
    for j in range(1, n + 1):
        dp[j][j] = 1

    # Заполняем таблицу
    for i in range(1, n + 1):
        for j in range(1, i):
            for k in range(j + 1, i + 1):
                if i - j >= 0:
                    dp[i][j] += dp[i - j][k]

    # Суммируем все возможные лесенки из n кубиков
    result = sum(dp[n])

    with open('output.txt', 'w') as f:
        f.write(str(result))

if __name__ == "__main__":
    main()

