def main():
    with open('input.txt', 'r') as f:
        w, h = map(int, f.readline().split())
        n = int(f.readline())

        events = []

        for _ in range(n):
            x1, y1, x2, y2 = map(int, f.readline().split())
            events.append((x1, y1, y2, 1))
            events.append((x2, y1, y2, -1))

        events.sort()

        total_covered = 0
        active_intervals = []

        def merge_intervals():
            if not active_intervals:
                return 0
            sorted_intervals = sorted(active_intervals, key=lambda x: x[0])
            merged = [sorted_intervals[0]]
            for current in sorted_intervals[1:]:
                last = merged[-1]
                if current[0] <= last[1]:
                    merged[-1] = (last[0], max(last[1], current[1]))
                else:
                    merged.append(current)
            return sum(interval[1] - interval[0] for interval in merged)

        i = 0
        while i < len(events):
            current_x = events[i][0]
            while i < len(events) and events[i][0] == current_x:
                x, y1, y2, typ = events[i]
                if typ == 1:
                    active_intervals.append((y1, y2))
                else:
                    active_intervals.remove((y1, y2))
                i += 1

            if i < len(events):
                next_x = events[i][0]
                covered_height = merge_intervals()
                total_covered += covered_height * (next_x - current_x)

        uncovered_area = w * h - total_covered

        with open('output.txt', 'w') as f:
            f.write(str(uncovered_area))

if __name__ == "__main__":
    main()

