long long makeNum(string s, bool wantMax) {
    if (s.empty()) return 0;

    bool negative = s[0] == '-';
    string digits = negative ? s.substr(1) : s;

    if (digits.empty()) return 0;

    sort(digits.begin(), digits.end());

    if (!negative) {
        if (!wantMax) {
            if (digits[0] == '0') {
                int firstNonZero = -1;
                for (int i = 0; i < digits.size(); i++) {
                    if (digits[i] != '0') {
                        firstNonZero = i;
                        break;
                    }
                }
                if (firstNonZero == -1) return 0;
                string res = "";
                res += digits[firstNonZero];
                for (int i = 0; i < firstNonZero; i++) res += '0';
                for (int i = firstNonZero + 1; i < digits.size(); i++) res += digits[i];
                return stoll(res);
            } else {
                return stoll(digits);
            }
        } else {
            reverse(digits.begin(), digits.end());
            if (digits[0] == '0') return 0;
            return stoll(digits);
        }
    } else {
        if (!wantMax) {
            reverse(digits.begin(), digits.end());
            return -stoll(digits);
        } else {
            if (digits[0] == '0') {
                int firstNonZero = -1;
                for (int i = 0; i < digits.size(); i++) {
                    if (digits[i] != '0') {
                        firstNonZero = i;
                        break;
                    }
                }
                if (firstNonZero == -1) return 0;
                string res = "";
                res += digits[firstNonZero];
                for (int i = 0; i < firstNonZero; i++) res += '0';
                for (int i = firstNonZero + 1; i < digits.size(); i++) res += digits[i];
                return -stoll(res);
            } else {
                return -stoll(digits);
            }
        }
    }
}

int main() {
    string a, b;
    cin >> a >> b;

    long long maxA = makeNum(a, true);
    long long minB = makeNum(b, false);

    cout << (maxA - minB) << endl;

    return 0;
}

