def get_cyclic_shifts(s):
    if not s:
        return set()
    shifts = set()
    n = len(s)
    for i in range(n):
        shifts.add(s[i:] + s[:i])
    return shifts

def count_substrings(text, patterns):
    count = 0
    n = len(text)
    for i in range(n):
        for j in range(i + 1, n + 1):
            substring = text[i:j]
            if substring in patterns:
                count += 1
    return count

def main():
    a, b = read_input()
    cyclic_shifts = get_cyclic_shifts(b)
    result = count_substrings(a, cyclic_shifts)

    with open('output.txt', 'w') as f:
        f.write(str(result))

if __name__ == '__main__':
    main()

