import sys
import math

def dist(x1, y1, x2, y2):
    return math.sqrt((x1 - x2) ** 2 + (y1 - y2) ** 2)

def main():
    data = []
    for line in sys.stdin:
        data.append(line.strip())

    first_line = list(map(int, data[0].split()))
    n = first_line[0]
    c = first_line[1]
    p = first_line[2]

    pigs = []
    for i in range(1, n + 1):
        x, y = map(int, data[i].split())
        pigs.append((x, y))

    xnet, ynet = map(int, data[n + 1].split())

    # Расстояния от точки подключения до каждого поросёнка
    direct = [dist(xnet, ynet, x, y) for x, y in pigs]

    min_total = float('inf')

    # Пробуем выбрать каждого поросёнка как первого подключённого
    for i in range(n):
        total = direct[i]  # от сети до i-го поросёнка
        # от i-го поросёнка ко всем остальным
        for j in range(n):
            if i != j:
                total += dist(pigs[i][0], pigs[i][1], pigs[j][0], pigs[j][1])
        if total < min_total:
            min_total = total

    cost = min_total * c
    # Гарантируется, что ответ либо целый, либо отличается от целого > 0.01,
    # поэтому можно округлять с небольшим запасом
    if cost <= p + 1e-5:
        print("YES")
    else:
        print("NO")

if __name__ == "__main__":
    main()

