def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def generate_prime_sequence(length):
    sequence = ""
    num = 2
    while len(sequence) < length:
        if is_prime(num):
            sequence += str(num)
        num += 1
    return sequence

with open('input.txt', 'r') as f:
