def ip_to_int(ip):
    return sum(int(octet) << (8 * (3 - i)) for i, octet in enumerate(ip.split('.')))

def mask_to_int(mask):
    return ip_to_int(mask)

def count_common_subnets():
    with open('input.txt', 'r') as f:
        n = int(f.readline().strip())
        masks = []
        for _ in range(n):
            mask = f.readline().strip()
            masks.append(mask_to_int(mask))

        m = int(f.readline().strip())
        results = []

        for _ in range(m):
            ip1_str, ip2_str = f.readline().strip().split()
            ip1 = ip_to_int(ip1_str)
            ip2 = ip_to_int(ip2_str)

            count = 0
            for mask in masks:
                if (ip1 & mask) == (ip2 & mask):
                    count += 1
            results.append(str(count))

    with open('output.txt', 'w') as f:
        f.write('\n'.join(results))

