import sys

def main():
    encoded = sys.stdin.readline().strip()
    n = len(encoded)
    base = 27
    result = []

    # Маппинг из символов в значения: '0'->0, ..., '9'->9, 'A'->10, ..., 'Q'->26
    char_to_val = {}
    for i in range(10):
        char_to_val[str(i)] = i
    for i in range(17):
        char_to_val[chr(ord('A') + i)] = 10 + i

    for pos in range(n):
        c = encoded[pos]
        val = char_to_val[c]
        # На позиции pos (0-индекс) номер символа в сообщении = pos + 1
        original_val = (val - (pos + 1)) % base
        if original_val == 27:
            original_val = 0
        # Обратное: 1-26 -> 'a'-'z', 0 -> пробел
        if original_val == 0:
            result.append(' ')
        else:
            result.append(chr(ord('a') + original_val - 1))

    print(''.join(result))

if __name__ == "__main__":
    main()

