def solve():
    with open('input.txt', 'r') as f:
        n, k = map(int, f.readline().split())

    def count_valid_numbers():
        if k > 31 or k < 0:
            return 0

        s = bin(n)[2:]
        length = len(s)

        if k >= length:
            return 0

        memo = {}

        def dp(pos, zeros, tight, started):
            if pos == length:
                return 1 if zeros == k and started else 0

            state = (pos, zeros, tight, started)
            if state in memo:
                return memo[state]

            limit = int(s[pos]) if tight else 1
            result = 0

            for digit in range(limit + 1):
                new_tight = tight and (digit == limit)
                new_started = started or (digit == 1)
                new_zeros = zeros + (1 if (digit == 0 and new_started) else 0)

                if new_zeros <= k:
                    result += dp(pos + 1, new_zeros, new_tight, new_started)

            memo[state] = result
            return result

        return dp(0, 0, True, False)

    result = count_valid_numbers()

    with open('output.txt', 'w') as f:
        f.write(str(result))

