    int maxArea = 0;
    for (int i = 0; i < N; i++) {
        vector<int> h = height[i];
        vector<int> left(M), right(M);

        for (int j = 0; j < M; j++) {
            int k = j - 1;
            while (k >= 0 && h[k] >= h[j]) {
                k = left[k] - 1;
            }
            left[j] = k + 1;
