			r := F(p[i].x - p[z].x)
			t := F(p[i].y - p[z].y)
			k := H(r, t)
			e := X*r/k + Y*t/k
			if e > o {
				h = i
				o = e
			}
			i++
		}
		X = F(p[h].x - p[z].x)
		Y = F(p[h].y - p[z].y)
		o = H(X, Y)
		X /= o
		Y /= o
		z = h
	}

	q = append(q, q[0])
	for l < len(q)-1 {
		f := q[l+1]
		a += (f.x - q[l].x) * (f.y + q[l].y)
		l++
	}

	a++
	Print(a / 2)
}

