int main() {
    int N, M;
    cin >> N >> M;

    vector<vector<Edge>> graph(N + 1);
    vector<int> indegree(N + 1, 0);

    for (int i = 0; i < M; i++) {
        int from, to, weight;
        cin >> from >> to >> weight;
        graph[from].push_back({to, weight});
        indegree[to]++;
    }

    vector<long long> dist(N + 1, LLONG_MIN);
    vector<bool> in_queue(N + 1, false);
    vector<int> count(N + 1, 0);
    queue<int> q;

    dist[1] = 0;
    q.push(1);
    in_queue[1] = true;

    bool has_positive_cycle = false;
    vector<bool> reachable(N + 1, false);
    vector<bool> can_reach_end(N + 1, false);

    // BFS для определения достижимости
    queue<int> bfs_q;
    bfs_q.push(1);
    reachable[1] = true;

    while (!bfs_q.empty()) {
        int u = bfs_q.front();
        bfs_q.pop();

        for (const Edge& e : graph[u]) {
            if (!reachable[e.to]) {
                reachable[e.to] = true;
                bfs_q.push(e.to);
            }
        }
    }

    // Проверка достижимости конца из каждой вершины
    vector<vector<bool>> visited(N + 1, vector<bool>(N + 1, false));
    for (int i = 1; i <= N; i++) {
        if (reachable[i]) {
            queue<int> check_q;
            check_q.push(i);
            visited[i][i] = true;

            while (!check_q.empty()) {
                int u = check_q.front();
                check_q.pop();

                for (const Edge& e : graph[u]) {
                    if (!visited[i][e.to]) {
                        visited[i][e.to] = true;
                        check_q.push(e.to);
                    }
                }
            }
            can_reach_end[i] = visited[i][N];
        }
    }

    // Алгоритм Беллмана-Форда для поиска кратчайшего пути и циклов
    for (int i = 0; i < N - 1; i++) {
        bool updated = false;
        for (int u = 1; u <= N; u++) {
            if (dist[u] == LLONG_MIN) continue;
            for (const Edge& e : graph[u]) {
                if (dist[e.to] < dist[u] + e.weight) {
                    dist[e.to] = dist[u] + e.weight;
                    updated = true;
                }
            }
        }
        if (!updated) break;
    }

    // Проверка на положительные циклы
    for (int u = 1; u <= N; u++) {
        if (dist[u] == LLONG_MIN) continue;
        for (const Edge& e : graph[u]) {
            if (dist[e.to] < dist[u] + e.weight && reachable[u] && can_reach_end[u] && can_reach_end[e.to]) {
                has_positive_cycle = true;
                break;
            }
        }
        if (has_positive_cycle) break;
    }

    if (has_positive_cycle) {
        cout << ":)" << endl;
    } else if (dist[N] == LLONG_MIN) {
        cout << ":(" << endl;
    } else {
        cout << dist[N] << endl;
    }

    return 0;
}

