def is_palindrome(s):
    return s == s[::-1]

def find_base(n):
    results = []
    for base in range(2, 37):
        num = n
        digits = []
        while num > 0:
            digits.append(num % base)
            num //= base
        s = ''.join(str(d) if d < 10 else chr(ord('A') + d - 10) for d in digits[::-1])
        if is_palindrome(s):
            results.append(base)
    return results

