            if (i % 2 == 0) {
                dp[i] = (dp[i - 1] + dp[i / 2]) % p;
            } else {
                dp[i] = dp[i - 1] % p;
            }
        }

        std::fprintf(fout, "%d", dp[k] % p);
        delete[] dp;
    }

    std::fclose(fin);
    std::fclose(fout);
    return 0;
