    slower = set()
    stack = [k]
    visited = set()

    while stack:
        horse = stack.pop()
        if horse not in visited:
            visited.add(horse)
            slower.add(horse)
            for slower_horse in graph[horse]:
                if slower_horse not in visited:
                    stack.append(slower_horse)

    # Поиск всех лошадей, которые быстрее K (могут победить K)
    faster = set()
    stack = [k]
    visited = set()

    while stack:
        horse = stack.pop()
        if horse not in visited:
            visited.add(horse)
            faster.add(horse)
            for faster_horse in reverse_graph[horse]:
                if faster_horse not in visited:
                    stack.append(faster_horse)

    # Удаляем саму лошадь K из множеств
    slower.discard(k)
    faster.discard(k)

    # Проверяем, что лошадь K быстрее всех остальных
