    for i in range(N):
        row = []
        for j in range(M):
            row.append(int(data[idx])); idx += 1
        grid.append(row)

    visited = [[False] * M for _ in range(N)]
    directions = [(1,0), (-1,0), (0,1), (0,-1)]

    def is_sink_connected(r, c, height):
        stack = [(r, c)]
        seen = set()
        is_sink = True

        while stack:
            cr, cc = stack.pop()
            if (cr, cc) in seen or visited[cr][cc] or grid[cr][cc] != height:
                continue
            seen.add((cr, cc))

            for dr, dc in directions:
                nr, nc = cr + dr, cc + dc
                if 0 <= nr < N and 0 <= nc < M:
                    if grid[nr][nc] < height:
                        is_sink = False
                    elif grid[nr][nc] == height and (nr, nc) not in seen:
                        stack.append((nr, nc))

        for r, c in seen:
            visited[r][c] = True
        return is_sink

    count = 0
    for i in range(N):
        for j in range(M):
            if not visited[i][j]:
                if is_sink_connected(i, j, grid[i][j]):
                    count += 1

    with open('OUTPUT.TXT', 'w') as f:
        f.write(str(count))

