#include <bits/stdc++.h>
using namespace std;

const int MAXN = 50;
const int INF = 1e9;

struct Edge {
    int to, cap, flow;
    Edge() {}
    Edge(int to, int cap) : to(to), cap(cap), flow(0) {}
};

vector<Edge> edges;
vector<int> g[MAXN];
int dist[MAXN], ptr[MAXN];

void addEdge(int from, int to, int cap) {
    edges.emplace_back(to, cap);
    edges.emplace_back(from, 0);
    g[from].push_back(edges.size() - 2);
    g[to].push_back(edges.size() - 1);
}

bool bfs(int s, int t) {
    fill(dist, dist + MAXN, -1);
    dist[s] = 0;
    queue<int> q;
    q.push(s);
    while (!q.empty()) {
        int v = q.front();
        q.pop();
        for (int id : g[v]) {
            int to = edges[id].to;
            if (dist[to] == -1 && edges[id].flow < edges[id].cap) {
                dist[to] = dist[v] + 1;
                q.push(to);
            }
        }
    }
    return dist[t] != -1;
}

int dfs(int v, int t, int flow) {
    if (v == t || flow == 0) return flow;
    for (; ptr[v] < g[v].size(); ptr[v]++) {
        int id = g[v][ptr[v]];
        int to = edges[id].to;
        if (dist[to] == dist[v] + 1) {
            int pushed = dfs(to, t, min(flow, edges[id].cap - edges[id].flow));
            if (pushed > 0) {
                edges[id].flow += pushed;
                edges[id ^ 1].flow -= pushed;
                return pushed;
            }
        }
    }
    return 0;
}

int maxFlow(int s, int t) {
    int flow = 0;
    while (bfs(s, t)) {
        fill(ptr, ptr + MAXN, 0);
        while (int pushed = dfs(s, t, INF))
            flow += pushed;
    }
    return flow;
}

int main() {
    ifstream cin("INPUT.TXT");
    ofstream cout("OUTPUT.TXT");

    int N, M;
    cin >> N >> M;

    vector<int> R(N), C(M);
    for (int i = 0; i < N; i++) cin >> R[i];
    for (int j = 0; j < M; j++) cin >> C[j];

    vector<vector<int>> Z(N, vector<int>(M));
    int fixedSum = 0;
    bool possible = true;

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) {
            cin >> Z[i][j];
            if (Z[i][j] != -1) {
                fixedSum += Z[i][j];
                R[i] -= Z[i][j];
                C[j] -= Z[i][j];
                if (R[i] < 0 || C[j] < 0) possible = false;
            }
        }
    }

    if (!possible) {
        cout << -1 << endl;
        return 0;
    }

    int s = 0, t = N + M + 1;
    for (int i = 0; i <= t; i++) g[i].clear();
    edges.clear();

    for (int i = 0; i < N; i++) {
        addEdge(s, i + 1, R[i]);
    }

    for (int j = 0; j < M; j++) {
        addEdge(N + j + 1, t, C[j]);
    }

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) {
            if (Z[i][j] == -1) {
                addEdge(i + 1, N + j + 1, 1e9);
            }
        }
    }

    int additionalFlow = maxFlow(s, t);

    cout << fixedSum + additionalFlow << endl;

    return 0;
}

