    for _ in range(N):
        P = int(data[idx]); idx += 1
        R = int(data[idx]); idx += 1
        Q = int(data[idx]); idx += 1
        F = int(data[idx]); idx += 1
        shops.append((P, R, Q, F))

    INF = 10**9
    dp = [INF] * (L + 101)
    dp[0] = 0

    for P, R, Q, F in shops:
        new_dp = dp[:]
        for have in range(len(dp)):
            if dp[have] == INF:
                continue
            for buy in range(F + 1):
                if buy == 0:
                    cost = 0
                elif buy < R:
                    cost = buy * P
                else:
                    cost = buy * Q
                new_total = have + buy
                if new_total < len(new_dp):
