using namespace std;

const int MAX_N = 30000;
long long a[MAX_N + 1];  // используем long long для надёжности при суммировании

int main() {
    ifstream fin("input.txt");
    ofstream fout("output.txt");

    int n;
    fin >> n;

    if (n == 0) {
        fout << 0;
        return 0;
    }

    for (int i = 0; i < n; ++i) {
        fin >> a[i];
    }

    if (n == 1) {
        fout << a[0];
        return 0;
    }
    if (n == 2) {
        fout << a[0] + a[1];
        return 0;
    }

    // Сортируем по возрастанию
    sort(a, a + n);

    long long current_sum = a[0] + a[1];  // сумма текущего "окна"
    long long max_sum = current_sum;
    int left = 0;  // левый указатель окна

    // Пытаемся расширять окно вправо, сохраняя условие "сплочённости":
    // для любого k в окне: a[k] <= a[i] + a[j] для любых i, j &#8800; k.
    // Достаточно проверить: наибольший элемент <= сумма двух наименьших.
    for (int right = 2; right < n; ++right) {
        // Пока условие нарушено: a[right] > a[left] + a[left + 1]
        while (a[right] > a[left] + a[left + 1]) {
            current_sum -= a[left];
            ++left;
            // После сдвига окно должно содержать хотя бы 2 элемента, иначе break
            if (left + 1 >= right) break;
        }
        // Теперь условие выполнено — добавляем a[right]
        current_sum += a[right];
        if (current_sum > max_sum) {
            max_sum = current_sum;
        }
    }

    fout << max_sum;
    return 0;
}

