int main() {
    int N;
    cin >> N;
    vector<int> prices(N);
    for (int i = 0; i < N; i++) {
        cin >> prices[i];
    }

    const int INF = 1e9;
    vector<vector<int>> dp(N + 1, vector<int>(N + 1, INF));
    vector<vector<int>> coupons_used(N + 1, vector<int>(N + 1, 0));

    dp[0][0] = 0;

    for (int i = 0; i < N; i++) {
        for (int coupons = 0; coupons <= N; coupons++) {
            if (dp[i][coupons] == INF) continue;

            int price = prices[i];

            if (coupons > 0) {
                dp[i + 1][coupons - 1] = min(dp[i + 1][coupons - 1], dp[i][coupons]);
                if (dp[i + 1][coupons - 1] == dp[i][coupons]) {
                    coupons_used[i + 1][coupons - 1] = coupons_used[i][coupons] + 1;
                }
            }

            dp[i + 1][coupons + (price > 100 ? 1 : 0)] = min(dp[i + 1][coupons + (price > 100 ? 1 : 0)], dp[i][coupons] + price);
            if (dp[i + 1][coupons + (price > 100 ? 1 : 0)] == dp[i][coupons] + price) {
                coupons_used[i + 1][coupons + (price > 100 ? 1 : 0)] = coupons_used[i][coupons];
            }
        }
    }

    int min_cost = INF;
    int best_coupons_left = -1;
    int best_coupons_used = -1;

    for (int coupons = 0; coupons <= N; coupons++) {
        if (dp[N][coupons] < min_cost) {
            min_cost = dp[N][coupons];
            best_coupons_left = coupons;
            best_coupons_used = coupons_used[N][coupons];
        } else if (dp[N][coupons] == min_cost && coupons > best_coupons_left) {
            best_coupons_left = coupons;
            best_coupons_used = coupons_used[N][coupons];
        }
    }

    cout << min_cost << endl;
    cout << best_coupons_left << " " << best_coupons_used << endl;

    return 0;
}

