import sys

def main():
    with open('INPUT.TXT', 'r') as f:
        A, B, C, D = map(int, f.readline().split())

    if A == 0 and B == 0 and C == 0 and D == 0:
        with open('OUTPUT.TXT', 'w') as f:
            f.write('-1\n')
        return

    roots = set()

    if A == 0 and B == 0:
        if C == 0:
            with open('OUTPUT.TXT', 'w') as f:
                f.write('0\n')
            return
        else:
            if D % C == 0:
                x = -D // C
                roots.add(x)
    elif A == 0:
        # B*x^2 + C*x + D = 0
        if B == 0:
            if C != 0 and D % C == 0:
                roots.add(-D // C)
        else:
            # x^2 + (C/B)*x + D/B = 0
            # B*x^2 + C*x + D = 0
            discriminant = C * C - 4 * B * D
            if discriminant >= 0:
                sqrt_d = int(discriminant ** 0.5)
                if sqrt_d * sqrt_d == discriminant:
                    if (-C + sqrt_d) % (2 * B) == 0:
                        roots.add((-C + sqrt_d) // (2 * B))
                    if (-C - sqrt_d) % (2 * B) == 0:
                        roots.add((-C - sqrt_d) // (2 * B))
    else:
        # A*x^3 + B*x^2 + C*x + D = 0
        # Поиск целых корней через делители свободного члена
        if D == 0:
            roots.add(0)
            # x*(A*x^2 + B*x + C) = 0
            discriminant = B * B - 4 * A * C
            if discriminant >= 0:
                sqrt_d = int(discriminant ** 0.5)
                if sqrt_d * sqrt_d == discriminant:
                    if (-B + sqrt_d) % (2 * A) == 0:
                        x = (-B + sqrt_d) // (2 * A)
                        if x != 0:
                            roots.add(x)
                    if (-B - sqrt_d) % (2 * A) == 0:
                        x = (-B - sqrt_d) // (2 * A)
                        if x != 0:
                            roots.add(x)
        else:
            # Ищем делители D
            for i in range(1, int(abs(D)**0.5) + 1):
                if D % i == 0:
                    candidates = [i, -i, D // i, -D // i]
                    for x in candidates:
                        if A * x * x * x + B * x * x + C * x + D == 0:
                            roots.add(x)

    roots = sorted(roots)

    with open('OUTPUT.TXT', 'w') as f:
        f.write(str(len(roots)) + '\n')
        for root in roots:
            f.write(str(root) + '\n')

if __name__ == "__main__":
    main()

