def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
    return True

def sum_of_digits(n):
    s = 0
    while n > 0:
        s += n % 10
        n //= 10
    return s

def simple_digital_root(n):
    if n < 10:
        if is_prime(n):
            return n
        else:
            return 0
    if is_prime(n):
        return n
    return simple_digital_root(sum_of_digits(n))

