    points = []
    idx = 1
    for i in range(n):
        x = float(data[idx])
        y = float(data[idx + 1])
        idx += 2
        points.append((x, y))

    if n == 1:
        print("0.00")
        return

    # Используем алгоритм Прима для поиска MST
    visited = [False] * n
    min_edge = [float('inf')] * n
    min_edge[0] = 0
    mst_cost = 0.0

    for _ in range(n):
        # Находим ближайшую непосещенную вершину
        u = -1
        for i in range(n):
            if not visited[i] and (u == -1 or min_edge[i] < min_edge[u]):
                u = i

        visited[u] = True
        mst_cost = max(mst_cost, min_edge[u])

        # Обновляем расстояния до непосещенных вершин
        for v in range(n):
            if not visited[v]:
                dist = distance(points[u], points[v])
                if dist < min_edge[v]:
                    min_edge[v] = dist

    print(f"{mst_cost:.2f}")

