import sys

MOD = 10**9 + 9

def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
    return True

def solve():
    n = int(sys.stdin.readline().strip())

    if n == 3:
        count = 0
        for num in range(100, 1000):
            if is_prime(num):
                count += 1
        print(count % MOD)
        return

    # Все трехзначные простые числа
    primes = [num for num in range(100, 1000) if is_prime(num)]

    # Создаем граф переходов: last_two -> list of primes starting with last_two
    transitions = {}
    for p in primes:
        first_two = p // 10
        if first_two not in transitions:
            transitions[first_two] = []
        transitions[first_two].append(p)

    # dp[p] - количество чисел длины L, оканчивающихся на простое p
    dp = {p: 1 for p in primes}

    # Строим числа длины от 4 до N
    for length in range(4, n + 1):
        new_dp = {}
        for prev in primes:
            if prev in dp:
                last_two = prev % 100
                if last_two in transitions:
                    for next_p in transitions[last_two]:
                        new_dp[next_p] = (new_dp.get(next_p, 0) + dp[prev]) % MOD
        dp = new_dp

    result = sum(dp.values()) % MOD
    print(result)

solve()

