    def is_recursive(start):
        visited = set()
        stack = [start]

        while stack:
            node = stack.pop()
            if node == start and visited:
                return True
            if node not in visited:
                visited.add(node)
                for neighbor in graph.get(node, []):
                    stack.append(neighbor)
        return False

    result = []
    for proc in proc_list:
        if is_recursive(proc):
            result.append("YES")
        else:
            result.append("NO")

