def cross(ax, ay, bx, by, cx, cy):
    return (bx - ax) * (cy - ay) - (by - ay) * (cx - ax)

def on_segment(ax, ay, bx, by, cx, cy):
    return min(ax, bx) <= cx <= max(ax, bx) and min(ay, by) <= cy <= max(ay, by)

def segments_intersect(x1, y1, x2, y2, x3, y3, x4, y4):
    d1 = cross(x1, y1, x2, y2, x3, y3)
    d2 = cross(x1, y1, x2, y2, x4, y4)
    d3 = cross(x3, y3, x4, y4, x1, y1)
    d4 = cross(x3, y3, x4, y4, x2, y2)

    if d1 * d2 <= 0 and d3 * d4 <= 0:
        if d1 == 0 and on_segment(x1, y1, x2, y2, x3, y3):
            return True
        if d2 == 0 and on_segment(x1, y1, x2, y2, x4, y4):
            return True
        if d3 == 0 and on_segment(x3, y3, x4, y4, x1, y1):
            return True
        if d4 == 0 and on_segment(x3, y3, x4, y4, x2, y2):
            return True
        if d1 != 0 or d2 != 0 or d3 != 0 or d4 != 0:
            return True

    return False

