            if (max_cost[w - W[i]] != INT_MIN) {
                max_cost[w] = max(max_cost[w], max_cost[w - W[i]] + P[i]);
            }
        }
    }

    if (min_cost[total_weight] == INT_MAX) {
        fout << "This is impossible." << endl;
    } else {
        fout << min_cost[total_weight] << " " << max_cost[total_weight] << endl;
    }

