def generate_partitions(n, max_val=None):
    if n == 0:
        return [[]]
    if max_val is None:
        max_val = n

    result = []
    for i in range(1, min(n, max_val) + 1):
        for p in generate_partitions(n - i, i):
            result.append([i] + p)
    return result

