    int total_combinations = 1 << (N - 1);
    bool found = false;

    for (int mask = 0; mask < total_combinations; mask++) {
        long long result = X[0];

        for (int i = 1; i < N; i++) {
            if (mask & (1 << (i - 1))) {
                result += X[i];
            } else {
                result -= X[i];
            }
        }

        if (result == S) {
            found = true;
            fout << X[0];
            for (int i = 1; i < N; i++) {
                if (mask & (1 << (i - 1))) {
                    fout << "+";
                } else {
                    fout << "-";
                }
                fout << X[i];
            }
            fout << "=" << S << endl;
            break;
        }
    }

    if (!found) {
        fout << "No solution" << endl;
    }

    fin.close();
    fout.close();

    return 0;
}

