    # Сортируем гангстеров по времени
    gangsters = [(t_arr[i], p_arr[i], s_arr[i]) for i in range(n)]
    gangsters.sort()

    # dp[time][s] = max wealth ending with door state s at time time
    # Но time может быть до 30000, поэтому будем использовать только нужные моменты
    events = {}
    for tm, p, s in gangsters:
        if tm not in events:
            events[tm] = []
        events[tm].append((p, s))

    # Все значимые времена + начальное и конечное
    times = sorted(events.keys())
    if 0 not in times:
        times.insert(0, 0)

    # dp[s] = max wealth ending with door state s
    dp = [-1] * (k + 1)
    dp[0] = 0

    prev_time = 0
    for time in times:
        if time == 0:
            # Обрабатываем гангстеров в нулевой момент
            if 0 in events:
                for p, s in events[0]:
                    if s <= k and dp[s] != -1:
                        dp[s] += p
            prev_time = 0
            continue

        # За прошедшее время дверь могла измениться
        time_diff = time - prev_time
        new_dp = [-1] * (k + 1)

        # Для каждого возможного состояния в прошлом
        for prev_s in range(k + 1):
            if dp[prev_s] == -1:
                continue
            # За time_diff единиц времени можно изменить состояние в пределах [prev_s - time_diff, prev_s + time_diff]
            for curr_s in range(k + 1):
                if abs(curr_s - prev_s) <= time_diff:
                    new_dp[curr_s] = max(new_dp[curr_s], dp[prev_s])

        dp = new_dp

        # Обрабатываем гангстеров в этот момент
        if time in events:
            for p, s in events[time]:
                if s <= k and dp[s] != -1:
                    dp[s] += p

        prev_time = time

    result = max(dp) if dp else 0
    result = max(0, result)

    with open('OUTPUT.TXT', 'w') as f:
        f.write(str(result))

