    m, y = month_c, year_c
    d = day_c

    # Пока не дойдём до дня рождения
    while not (m == month_b and d == day_b):
        days += 1
        d += 1

        # Переводим дни в следующий месяц/год при необходимости
        if d > days_in_month(m, y):
