using namespace std;

struct Point {
    int x, y;
    Point(int x = 0, int y = 0) : x(x), y(y) {}

    bool operator<(const Point& p) const {
        if (x != p.x) return x < p.x;
        return y < p.y;
    }
};

bool collinear(const Point& a, const Point& b, const Point& c) {
    return (b.x - a.x) * (c.y - a.y) == (c.x - a.x) * (b.y - a.y);
}

int main() {
    int N;
    cin >> N;

    if (N > 300) {
        cout << "NO" << endl;
        return 0;
    }

    vector<Point> points;
    set<Point> used;

    points.push_back(Point(0, 0));
    used.insert(Point(0, 0));

    for (int y = 1; points.size() < N; y++) {
        for (int x = 0; x <= 200 && points.size() < N; x++) {
            Point p(x, y);
            if (used.count(p)) continue;

            bool valid = true;
            for (int i = 0; i < points.size(); i++) {
                for (int j = i + 1; j < points.size(); j++) {
                    if (collinear(points[i], points[j], p)) {
                        valid = false;
                        break;
                    }
                }
                if (!valid) break;
            }

            if (valid) {
                points.push_back(p);
                used.insert(p);
            }
        }
    }

    if (points.size() < N) {
        cout << "NO" << endl;
    } else {
        cout << "YES" << endl;
        for (const auto& p : points) {
            cout << p.x << " " << p.y << endl;
        }
    }

    return 0;
}

