        string trimmed = "";
        int start = 0, end = s.length() - 1;
        while (start < s.length() && s[start] == ' ') start++;
        while (end >= 0 && s[end] == ' ') end--;
        if (start <= end) {
            trimmed = s.substr(start, end - start + 1);
        }

        if (trimmed.length() > K) {
            out << "Impossible." << endl;
            out.close();
            return 0;
        }

        int totalSpaces = K - trimmed.length();
        int leftSpaces = totalSpaces / 2;
        int rightSpaces = totalSpaces - leftSpaces;

        if (leftSpaces > rightSpaces) {
            out << "Impossible." << endl;
            out.close();
            return 0;
        }

        string result = string(leftSpaces, ' ') + trimmed + string(rightSpaces, ' ');
        lines[i] = result;
    }

    for (int i = 0; i < N; i++) {
        out << lines[i] << endl;
    }
