def main():
    with open('INPUT.TXT', 'r') as f:
        lines = f.readlines()

    n = int(lines[0])
    grid = [list(line.strip()) for line in lines[1:1+n]]

    start = None
    end = None

    for i in range(n):
        for j in range(n):
            if grid[i][j] == '@':
                start = (i, j)
            elif grid[i][j] == 'X':
                end = (i, j)

    if start is None or end is None:
        with open('OUTPUT.TXT', 'w') as f:
            f.write('N\n')
        return

    # BFS для поиска кратчайшего пути
    queue = deque()
    queue.append((start[0], start[1]))
    visited = [[False] * n for _ in range(n)]
    visited[start[0]][start[1]] = True
    parent = {}

    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    found = False
    while queue:
        x, y = queue.popleft()

        if (x, y) == end:
            found = True
            break

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < n and not visited[nx][ny]:
                if grid[nx][ny] in ['.', 'X']:
                    visited[nx][ny] = True
                    parent[(nx, ny)] = (x, y)
                    queue.append((nx, ny))

    if not found:
        with open('OUTPUT.TXT', 'w') as f:
            f.write('N\n')
        return

    # Восстановление пути
    path = []
    current = end
    while current != start:
        path.append(current)
        current = parent[current]

    # Формирование результата
    with open('OUTPUT.TXT', 'w') as f:
        f.write('Y\n')
        result_grid = [row[:] for row in grid]

        # Помечаем путь, кроме начальной позиции
        for x, y in path:
            if (x, y) == end:
                result_grid[x][y] = '+'
            else:
                result_grid[x][y] = '+'

        for row in result_grid:
            f.write(''.join(row) + '\n')

if __name__ == '__main__':
