    N, K = map(int, input().split())

    if N == 1:
        print(2, 0)
        return

    best_d = 2
    best_l = 0

    # Проверяем небольшие основания
    max_d = min(10**6, N + 2)
    for D in range(2, max_d):
        n = N
        count = 0
        while n > 0 and n % D == K:
            count += 1
            n //= D
        if count > best_l:
            best_l = count
            best_d = D

    # Проверяем большие основания через делители (N - K)
    if K < N:
        diff = N - K
        # Проверяем все делители diff
        d = 1
        while d * d <= diff:
            if diff % d == 0:
                for candidate in [d, diff // d]:
                    if candidate > max_d and candidate <= 10**12:
                        n = N
                        count = 0
                        while n > 0 and n % candidate == K:
                            count += 1
                            n //= candidate
                        if count > best_l:
                            best_l = count
                            best_d = candidate
            d += 1

    # Также проверим D = N - K напрямую, если подходит
    if K < N:
        D = N - K
        if D > max_d and D <= 10**12:
            n = N
            count = 0
            while n > 0 and n % D == K:
                count += 1
                n //= D
            if count > best_l:
                best_l = count
                best_d = D

    # Проверим D = N + 1 (если K == 0, то N в СС с основанием N+1 даст запись "10")
    if K == 0 and N + 1 > max_d:
        count = 0
        n = N
        while n > 0 and n % (N + 1) == 0:
            count += 1
            n //= (N + 1)
        if count > best_l:
            best_l = count
            best_d = N + 1

    print(best_d, best_l)

