def fib_sequence(n):
    fib = [1, 2]
    while len(fib) < n:
        fib.append(fib[-1] + fib[-2])
    return fib

def fib_to_dec(s):
    fib = fib_sequence(len(s))
    result = 0
    for i in range(len(s)):
        if s[i] == '1':
            result += fib[len(s) - 1 - i]
    return result

def dec_to_fib(n):
    if n == 0:
        return "0"
    fib = [1, 2]
    while fib[-1] < n:
        fib.append(fib[-1] + fib[-2])
    if fib[-1] > n:
        fib.pop()

    result = []
    for f in reversed(fib):
        if n >= f:
            result.append('1')
            n -= f
        else:
            result.append('0')
    return ''.join(result)

def main():
    with open('INPUT.TXT', 'r') as f:
        a = f.readline().strip()
        b = f.readline().strip()

    num_a = fib_to_dec(a)
    num_b = fib_to_dec(b)
    total = num_a + num_b

    result = dec_to_fib(total)

    with open('OUTPUT.TXT', 'w') as f:
        f.write(result)

