    fin >> H;

    vector<int> order(H);
    for (int i = 0; i < H; ++i) {
        fin >> order[i];
        --order[i];
    }

    string encoded;
    fin.ignore();
    getline(fin, encoded);

    int length = encoded.length();
    int cols = (length + H - 1) / H;

    vector<int> row_lengths(H);
    vector<string> rows(H);

    int full_cols = length % H;
    int chars_per_col = length / H;

    for (int i = 0; i < H; ++i) {
        if (i < full_cols) {
            row_lengths[i] = chars_per_col + 1;
        } else {
            row_lengths[i] = chars_per_col;
        }
    }

    int pos = 0;
    for (int i = 0; i < H; ++i) {
        int original_row = order[i];
        rows[original_row] = encoded.substr(pos, row_lengths[original_row]);
        pos += row_lengths[original_row];
    }

    string result;
    for (int col = 0; col < cols; ++col) {
        for (int row = 0; row < H; ++row) {
            if (col < rows[row].length()) {
                result += rows[row][col];
            }
        }
    }

    fout << result;

    return 0;
}

