def solve():
    with open('INPUT.TXT', 'r') as f:
        lines = f.readlines()

    N, K, P = map(int, lines[0].split())
    moves = [int(lines[i]) for i in range(1, 1 + P)]

    # Проигрышная позиция — это когда остаток делится на (K+1)
    def is_losing_position(n):
        return n % (K + 1) == 0

    result = []
    remaining = N

    for move in moves:
        if is_losing_position(remaining):
            # Текущая позиция проигрышная — любой ход правильный
            result.append('T')
        else:
            # Позиция выигрышная — правильный ход ведёт в проигрышную позицию
            next_remaining = remaining - move
            if is_losing_position(next_remaining):
                result.append('T')
            else:
                result.append('F')

        remaining -= move

    with open('OUTPUT.TXT', 'w') as f:
        for res in result:
            f.write(res + '\n')

solve()

