def is_prime(x):
    if x < 2:
        return False
    if x == 2:
        return True
    if x % 2 == 0:
        return False
    i = 3
    while i * i <= x:
        if x % i == 0:
            return False
        i += 2
    return True

def is_two_prime(n):
    digits = sorted(str(n))
    asc = int(''.join(digits))
    desc = int(''.join(digits[::-1]))
    return is_prime(asc) and is_prime(desc)

