def main():
    with open('INPUT.TXT', 'r') as f:
        n, k = map(int, f.readline().split())
        maze = []
        for _ in range(n):
            maze.append(f.readline().strip())

    # directions: up, down, left, right
    dx = [-1, 1, 0, 0]
    dy = [0, 0, -1, 1]

    # dp[step][i][j] - number of ways to reach cell (i,j) in 'step' steps
    dp = [[[0] * n for _ in range(n)] for _ in range(k + 1)]

    # Starting position (0,0) in 0 steps
    dp[0][0][0] = 1

    # Fill dp table for each step
    for step in range(1, k + 1):
        for i in range(n):
            for j in range(n):
                if maze[i][j] == '1':
                    continue
                # Try all 4 directions
                for d in range(4):
                    ni, nj = i + dx[d], j + dy[d]
                    if 0 <= ni < n and 0 <= nj < n and maze[ni][nj] == '0':
                        dp[step][i][j] += dp[step - 1][ni][nj]

    # Result: number of ways to reach (n-1, n-1) in exactly k steps
    result = dp[k][n-1][n-1]

    with open('OUTPUT.TXT', 'w') as f:
        f.write(str(result))

if __name__ == "__main__":
    main()

