def solve():
    with open('INPUT.TXT', 'r') as f:
        A = f.readline().strip()
        B = int(f.readline().strip())

    def value_in_base(s, base):
        try:
            return int(s, base)
        except:
            return -1

    def min_base(s):
        max_char = max(s)
        if max_char.isdigit():
            return max(2, int(max_char) + 1)
        else:
            return max(11, ord(max_char) - ord('A') + 11)

    start_base = min_base(A)
    ans = 0

    for base in range(start_base, 37):
        val = value_in_base(A, base)
        if val == B:
            ans = base
            break
        elif val > B:
            break

    with open('OUTPUT.TXT', 'w') as f:
        f.write(str(ans))

