def get_rotations(cube):
    # cube = [front, back, top, bottom, left, right]
    rotations = []

    # Основные повороты вокруг трех осей
    def rotate_vertical(c):  # вокруг вертикальной оси (top-bottom)
        return [c[4], c[5], c[2], c[3], c[1], c[0]]

    def rotate_horizontal(c):  # вокруг горизонтальной оси (left-right)
        return [c[2], c[3], c[1], c[0], c[4], c[5]]

    def rotate_depth(c):  # вокруг оси вглубь (front-back)
        return [c[0], c[1], c[5], c[4], c[3], c[2]]

    # Генерируем все 24 поворота
    current = cube[:]
    for _ in range(4):
        current = rotate_vertical(current)
        temp = current[:]
        for _ in range(4):
            temp = rotate_horizontal(temp)
            rotations.append(temp[:])

    current = rotate_horizontal(cube)
    for _ in range(4):
        current = rotate_vertical(current)
        temp = current[:]
        for _ in range(4):
            temp = rotate_horizontal(temp)
            rotations.append(temp[:])

    return rotations

