def main():
    with open('INPUT.TXT', 'r') as f:
        n = int(f.readline())
        graph = []
        for _ in range(n):
            row = list(map(int, f.readline().split()))
            graph.append(row)

    # Максимизируем размер наибольшей группы
    # Перебираем возможные размеры групп от 5 до 1
    best_groups = [[i] for i in range(n)]  # fallback

    def is_clique(group):
        for i in range(len(group)):
            for j in range(i + 1, len(group)):
                if graph[group[i]][group[j]] == 0:
                    return False
        return True

    # Перебираем все возможные разбиения с помощью битовых масок
    # Ищем максимальный размер группы, который можно достичь
    max_possible_size = 1
    for mask in range(1, 1 << n):
        group = []
        for i in range(n):
            if mask & (1 << i):
                group.append(i)
        if len(group) <= 5 and is_clique(group):
            max_possible_size = max(max_possible_size, len(group))

    # Теперь строим разбиение, используя группы размера max_possible_size
    def find_cliques_of_size(size):
        cliques = []
        for mask in range(1, 1 << n):
            group = []
            for i in range(n):
                if mask & (1 << i):
                    group.append(i)
            if len(group) == size and is_clique(group):
                cliques.append(group[:])
        return cliques

    # Жадно строим разбиение
    used = [False] * n
    groups = []

    # Пробуем составить группы начиная с максимального размера
    for size in range(max_possible_size, 0, -1):
        cliques = find_cliques_of_size(size)
        # Сортируем по количеству неиспользованных людей в клике
        cliques.sort(key=lambda x: -len([p for p in x if not used[p]]))

        for clique in cliques:
            if all(not used[i] for i in clique):
                groups.append(clique)
                for i in clique:
                    used[i] = True

    # Оставшиеся люди - каждый в свою группу
    for i in range(n):
        if not used[i]:
            groups.append([i])

    # Формируем ответ
    result_groups = [0] * n
    for group_idx, group in enumerate(groups):
        for person in group:
            result_groups[person] = group_idx + 1

    with open('OUTPUT.TXT', 'w') as f:
        f.write(str(len(groups)) + '\n')
        f.write(' '.join(map(str, result_groups)) + '\n')

if __name__ == '__main__':
