#include <bits/stdc++.h>
using namespace std;

int n;
vector<string> words;
vector<string> square1, square2;
vector<bool> used;

bool canFormSquare(const vector<string>& w, vector<string>& result) {
    vector<string> grid(n);
    vector<bool> used_local(n, false);

    function<bool(int)> backtrack = [&](int row) {
        if (row == n) {
            result = grid;
            return true;
        }

        for (int i = 0; i < n; i++) {
            if (used_local[i]) continue;

            bool valid = true;
            for (int j = 0; j < row; j++) {
                if (w[i][j] != grid[j][row]) {
                    valid = false;
                    break;
                }
            }

            if (valid) {
                grid[row] = w[i];
                used_local[i] = true;

                if (backtrack(row + 1)) return true;

                used_local[i] = false;
            }
        }
        return false;
    };

    return backtrack(0);
}

bool solve() {
    for (int mask = 0; mask < (1 << (2 * n)); mask++) {
        if (__builtin_popcount(mask) != n) continue;

        vector<string> group1, group2;

        for (int i = 0; i < 2 * n; i++) {
            if (mask & (1 << i)) {
                group1.push_back(words[i]);
            } else {
                group2.push_back(words[i]);
            }
        }

        vector<string> sq1, sq2;
        if (canFormSquare(group1, sq1) && canFormSquare(group2, sq2)) {
            square1 = sq1;
            square2 = sq2;
            return true;
        }
    }
    return false;
}

int main() {
    ifstream cin("INPUT.TXT");
    ofstream cout("OUTPUT.TXT");

    cin >> n;
    words.resize(2 * n);

    for (int i = 0; i < 2 * n; i++) {
        cin >> words[i];
    }

    solve();

    for (const string& s : square1) {
        cout << s << endl;
    }
    cout << endl;
    for (const string& s : square2) {
        cout << s << endl;
    }

    return 0;
}

