import sys

def main():
    input_data = sys.stdin.read().strip().split()
    n = int(input_data[0])
    villages = []

    for i in range(n):
        x = int(input_data[2 * i + 1])
        y = int(input_data[2 * i + 2])
        villages.append((x, y))

    x1, x2 = villages[0][0], villages[1][0]
    if x1 > x2:
        x1, x2 = x2, x1

    # Функция для вычисления производной суммы расстояний
    def derivative(x):
        d = 0.0
        for vx, vy in villages:
            dx = x - vx
            dist_sq = dx * dx + vy * vy
            if dist_sq == 0:
                continue
            d += dx / (dist_sq ** 0.5)
        return d

    # Бинарный поиск по оптимальной точке (где производная меняет знак)
    left, right = float(x1), float(x2)
    for _ in range(100):
        mid = (left + right) / 2
        if derivative(mid) <= 0:
            left = mid
        else:
            right = mid

    print(f"{(left + right) / 2:.6f}")

if __name__ == "__main__":
    main()

