using namespace std;

int main() {
    ifstream fin("INPUT.TXT");
    ofstream fout("OUTPUT.TXT");

    int N, M, K;
    fin >> N >> M >> K;

    if (N == 0) {
        fout << (int)ceil((double)M / K) << endl;
        return 0;
    }

    if (M < 2) {
        fout << 0 << endl;
        return 0;
    }

    int buses_with_kids = 0;
    int remaining_kids = N;
    int remaining_adults = M;

    while (remaining_kids > 0 && remaining_adults >= 2) {
        int kids_in_bus = min(remaining_kids, K - 2);
        int adults_in_bus = min(remaining_adults, K - kids_in_bus);
        if (adults_in_bus < 2) {
            adults_in_bus = 2;
            kids_in_bus = min(remaining_kids, K - adults_in_bus);
        }

        remaining_kids -= kids_in_bus;
        remaining_adults -= adults_in_bus;
        buses_with_kids++;

        if (kids_in_bus == 0 && remaining_kids > 0) {
            break;
        }
    }

    if (remaining_kids > 0) {
        fout << 0 << endl;
        return 0;
    }

    int remaining_adults_buses = (int)ceil((double)remaining_adults / K);
    int total_buses = buses_with_kids + remaining_adults_buses;

    fout << total_buses << endl;

    return 0;
}

