    if n % 2 == 0:
        # n четное
        if n == 2:
            print("2 1")
        else:
            # n >= 4, четное
            # Если n делится на 2, то раскладываем на тройки и двойки
            # Приоритет - тройки, но если останется 2, то добавляем двойку
            threes = n // 3
            remainder = n % 3

            if remainder == 0:
                print(f"3 {threes}")
            elif remainder == 1:
                # Заменяем одну тройку на две двойки: 3+1 -> 2+2
                threes -= 1
                print(f"2 2")
                if threes > 0:
                    print(f"3 {threes}")
            else:  # remainder == 2
                # Остается одна двойка
                print(f"2 1")
                if threes > 0:
                    print(f"3 {threes}")
    else:
        # n нечетное
        if n == 3:
