import sys

def main():
    with open('INPUT.TXT', 'r') as f:
        lines = f.readlines()

    m, n = map(int, lines[0].split())
    matrix = []
    for i in range(1, m + 1):
        row = list(map(int, lines[i].split()))
        matrix.append(row)

    # dp[i][j] - минимальный вес пути до ячейки (i, j)
    dp = [[0] * n for _ in range(m)]

    # Инициализация первого столбца
    for i in range(m):
        dp[i][0] = matrix[i][0]

    # Заполнение таблицы
    for j in range(1, n):
        for i in range(m):
            dp[i][j] = float('inf')
            # Проверяем три возможных предыдущих позиции: сверху, прямо, снизу
            for di in [-1, 0, 1]:
                pi = i + di
                if 0 <= pi < m:
                    if dp[pi][j-1] < dp[i][j]:
                        dp[i][j] = dp[pi][j-1]
            dp[i][j] += matrix[i][j]

    # Находим минимальный вес в последнем столбце
    min_cost = min(dp[i][n-1] for i in range(m))

    # Восстанавливаем путь
    path = [0] * n
    # Находим лексикографически минимальную строку с минимальной стоимостью
    last_row = m
    for i in range(m):
        if dp[i][n-1] == min_cost:
            last_row = i
            break
    path[n-1] = last_row + 1  # +1 так как нумерация с 1

    # Восстанавливаем путь с конца
    for j in range(n-1, 0, -1):
        prev_cost = dp[path[j]-1][j] - matrix[path[j]-1][j]
        prev_row = m
        for i in range(m):
            if dp[i][j-1] == prev_cost:
                # Проверяем, что переход возможен
                if abs(i - (path[j]-1)) <= 1:
                    if i < prev_row:
                        prev_row = i
        path[j-1] = prev_row + 1

    # Записываем результат
    with open('OUTPUT.TXT', 'w') as f:
        f.write(' '.join(map(str, path)) + '\n')
        f.write(str(min_cost) + '\n')

if __name__ == '__main__':
    main()

