def main():
    with open('INPUT.TXT', 'r') as f:
        n = int(f.readline())
        rectangles = []
        for _ in range(n):
            x1, y1, x2, y2 = map(int, f.readline().split())
            rectangles.append((x1, y1, x2, y2))

    # Проверка пересечения или касания сторонами (но не только углами)
    def connected(rect1, rect2):
        x1, y1, x2, y2 = rect1
        x3, y3, x4, y4 = rect2

        # Пересечение по x и y
        x_overlap = max(0, min(x2, x4) - max(x1, x3))
        y_overlap = max(0, min(y2, y4) - max(y1, y3))

        # Если есть пересечение площади > 0
        if x_overlap > 0 and y_overlap > 0:
            return True

        # Проверка касания сторонами (но не углами)
        # Касание по вертикальной стороне: x2 == x3 или x4 == x1 и пересечение по y
        vert_touch = (x2 == x3 or x4 == x1) and y_overlap > 0
        # Касание по горизонтальной стороне: y2 == y3 или y4 == y1 и пересечение по x
        horiz_touch = (y2 == y3 or y4 == y1) and x_overlap > 0

        return vert_touch or horiz_touch

    # Строим граф связности и находим компоненты связности
    visited = [False] * n
    figures = []

    def dfs(i, comp):
        stack = [i]
        while stack:
            idx = stack.pop()
            if visited[idx]:
                continue
            visited[idx] = True
            comp.append(rectangles[idx])
            for j in range(n):
                if not visited[j] and connected(rectangles[idx], rectangles[j]):
                    stack.append(j)

    for i in range(n):
        if not visited[i]:
            comp = []
            dfs(i, comp)
            figures.append(comp)

    # Площадь объединения прямоугольников методом перебора клеток
    def area_of_figure(rects):
        if not rects:
            return 0

        # Маленький диапазон координат — можно использовать сетку
        grid = set()
        for x1, y1, x2, y2 in rects:
            for x in range(x1, x2):
                for y in range(y1, y2):
                    grid.add((x, y))

        return len(grid)

    max_area = 0
    for figure in figures:
        area = area_of_figure(figure)
        if area > max_area:
            max_area = area

    with open('OUTPUT.TXT', 'w') as f:
        f.write(str(max_area))

