def main():
    with open('INPUT.TXT', 'r') as f:
        m = int(f.readline().strip())

        graph = defaultdict(list)

        for _ in range(m):
            line = f.readline().strip()
            if '->' in line:
                parts = line.split('->')
                if len(parts) == 2:
                    src = parts[0].strip()
                    dst = parts[1].strip()
                    graph[src].append(dst)

        start = f.readline().strip()
        target = f.readline().strip()

    if start == target:
        result = 0
    else:
        queue = deque([(start, 0)])
        visited = {start}

        result = -1
        while queue:
            substance, steps = queue.popleft()

            for next_substance in graph[substance]:
                if next_substance == target:
                    result = steps + 1
                    queue.clear()
                    break

                if next_substance not in visited:
                    visited.add(next_substance)
                    queue.append((next_substance, steps + 1))

    with open('OUTPUT.TXT', 'w') as f:
        f.write(str(result))

if __name__ == '__main__':
