def main():
    with open('INPUT.TXT', 'r') as f:
        n = int(f.readline())
        graph = []
        for _ in range(n):
            row = list(map(int, f.readline().split()))
            graph.append(row)

    # Считаем общее количество двусторонних рёбер
    total_edges = 0
    for i in range(n):
        for j in range(i + 1, n):
            if graph[i][j] == 1:
                total_edges += 1

    # Ищем мосты с помощью алгоритма Тарьяна
    ids = [-1] * n
    low = [0] * n
    visited = [False] * n
    parent = [-1] * n
    bridge_count = 0
    id_counter = 0

    def dfs(at, p):
        nonlocal id_counter, bridge_count
        visited[at] = True
        id_counter += 1
        ids[at] = low[at] = id_counter

        for to in range(n):
            if graph[at][to] == 1:
                if to == p:
                    continue
                if not visited[to]:
                    parent[to] = at
                    dfs(to, at)
                    low[at] = min(low[at], low[to])
                    if ids[at] < low[to]:
                        bridge_count += 1
                else:
                    low[at] = min(low[at], ids[to])

    for i in range(n):
        if not visited[i]:
            dfs(i, -1)

    # Максимальное число дорог, которые можно сделать односторонними
    result = total_edges - bridge_count

    with open('OUTPUT.TXT', 'w') as f:
        f.write(str(result))

if __name__ == '__main__':
