from collections import deque

def flip_state(state, pos):
    """Применяет ход к позиции pos в состоянии state (16-битное число)"""
    flips = [pos]
    r, c = pos // 4, pos % 4

    # Добавляем соседей: сверху, снизу, слева, справа
    if r > 0: flips.append(pos - 4)
    if r < 3: flips.append(pos + 4)
    if c > 0: flips.append(pos - 1)
    if c < 3: flips.append(pos + 1)

    # Инвертируем биты
    for p in flips:
        state ^= (1 << p)
    return state

def solve():
    # Читаем вход
    with open('INPUT.TXT', 'r') as f:
        lines = [f.readline().strip() for _ in range(4)]

    # Преобразуем в битовое представление: 1 = 'w', 0 = 'b'
    state = 0
    for i in range(4):
        for j in range(4):
            if lines[i][j] == 'w':
                state |= (1 << (i * 4 + j))

    # Проверяем, не решена ли задача сразу
    if state == 0 or state == (1 << 16) - 1:
        with open('OUTPUT.TXT', 'w') as f:
            f.write('0\n')
        return

    # BFS
    queue = deque([(state, 0)])
    visited = set([state])

    while queue:
        curr_state, moves = queue.popleft()

        if moves >= 15:  # Ограничение на максимальное количество ходов
            continue

        # Пробуем все 16 позиций
        for pos in range(16):
            next_state = flip_state(curr_state, pos)

            # Проверяем, достигнут ли целевой&#29366;&#24577;
            if next_state == 0 or next_state == (1 << 16) - 1:
                with open('OUTPUT.TXT', 'w') as f:
                    f.write(str(moves + 1) + '\n')
                return

            if next_state not in visited:
                visited.add(next_state)
                queue.append((next_state, moves + 1))

    with open('OUTPUT.TXT', 'w') as f:
        f.write('Impossible\n')

solve()

