import math

def lcm(a, b):
    return a * b // math.gcd(a, b)

def max_steps(n):
    # Нужно найти максимальное число, которое может быть порядком перестановки
    # Это максимальное значение НОК длин циклов разбиения числа n
    # Используем динамическое программирование
    max_lcm = [0] * (n + 1)
    max_lcm[0] = 1

    for i in range(1, n + 1):
        max_lcm[i] = i  # худший случай - один цикл длины i
        for j in range(1, i):
            max_lcm[i] = max(max_lcm[i], lcm(j, max_lcm[i - j]))

    return max_lcm[n]

n = int(input())
print(max_steps(n))

