def F(a, b, c):
    if a <= 0 or b <= 0 or c <= 0:
        return 1
    if a > 20 or b > 20 or c > 20:
        return F(20, 20, 20)

    memo = {}

    def dp(x, y, z):
        if x <= 0 or y <= 0 or z <= 0:
            return 1
        if (x, y, z) in memo:
            return memo[(x, y, z)]

        if x < y and y < z:
            result = dp(x, y, z-1) + dp(x, y-1, z-1) - dp(x, y-1, z)
        else:
            result = dp(x-1, y, z) + dp(x-1, y-1, z) + dp(x-1, y, z-1) - dp(x-1, y-1, z-1)

        memo[(x, y, z)] = result
        return result

    return dp(a, b, c)

