def main():
    with open('INPUT.TXT', 'r') as f:
        n = int(f.readline())
        weights = list(map(int, f.readline().split()))

    total = sum(weights)

    if total % 3 != 0:
        with open('OUTPUT.TXT', 'w') as f:
            f.write('0\n')
        return

    target = total // 3
    used = [False] * n
    result = []

    # Ищем подмножество с суммой target
    def find_subset(curr_sum, start_idx):
        if curr_sum == target:
            return True
        if curr_sum > target or start_idx >= n:
            return False

        for i in range(start_idx, n):
            if not used[i]:
                used[i] = True
                result.append(i + 1)  # номера с 1
                if find_subset(curr_sum + weights[i], i + 1):
                    return True
                result.pop()
                used[i] = False

        return False

    if find_subset(0, 0):
        with open('OUTPUT.TXT', 'w') as f:
            f.write(f'{len(result)}\n')
            if result:
                f.write(' '.join(map(str, result)) + '\n')
    else:
        with open('OUTPUT.TXT', 'w') as f:
            f.write('0\n')

if __name__ == '__main__':
    main()

