def main():
    with open('INPUT.TXT', 'r') as f:
        n, m = map(int, f.readline().split())
        data = list(map(int, f.readline().split()))

    k = data[0]
    protected = set()
    idx = 1
    for _ in range(k):
        y, x = data[idx], data[idx + 1]
        protected.add((y, x))
        idx += 2

    total_cells = n * m
    unprotected = total_cells - k

    if unprotected == 0:
        result = 0
    else:
        # Клеточное поле - разбиваем на связные компоненты
        visited = set()
        components = 0

        def dfs(y, x):
            stack = [(y, x)]
            visited.add((y, x))
            while stack:
                cy, cx = stack.pop()
                for ny, nx in [(cy-1, cx), (cy+1, cx), (cy, cx-1), (cy, cx+1)]:
                    if 1 <= ny <= n and 1 <= nx <= m and (ny, nx) not in protected and (ny, nx) not in visited:
                        visited.add((ny, nx))
                        stack.append((ny, nx))

        for i in range(1, n + 1):
            for j in range(1, m + 1):
                if (i, j) not in protected and (i, j) not in visited:
                    components += 1
                    dfs(i, j)

        result = components

    with open('OUTPUT.TXT', 'w') as f:
        f.write(str(result))

if __name__ == '__main__':
