import math

def solve():
    n = int(sys.stdin.readline().strip())

    def count_prime_factors(num, p):
        count = 0
        power = p
        while power <= num:
            count += num // power
            if power > num // p:
                break
            power *= p
        return count

    def prime_factorization(x):
        factors = {}
        d = 2
        while d * d <= x:
            while x % d == 0:
                factors[d] = factors.get(d, 0) + 1
                x //= d
            d += 1 if d == 2 else 2
        if x > 1:
            factors[x] = factors.get(x, 0) + 1
        return factors

    prime_factors = prime_factorization(n)

    result = float('inf')

    for prime, exp_in_n in prime_factors.items():
        exp_in_factorial = count_prime_factors(n, prime)
        max_k_for_prime = exp_in_factorial // exp_in_n
        result = min(result, max_k_for_prime)

    print(result)

